import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;

public class Main {
    private static final int COUNT = 100_000;

    public static void main(String[] args) {
        // Populate both collections with identical data
        List<Integer> arrayList = new ArrayList<>(COUNT);
        List<Integer> linkedList = new LinkedList<>();

        for (int i = 0; i < COUNT; i++) {
            arrayList.add(i);
            linkedList.add(i);
        }

        // 1. Benchmark ArrayList Traversal
        long startArr = System.nanoTime();
        long sumArr = 0;
        for (int val : arrayList) {
            sumArr += val;
        }
        long durationArr = System.nanoTime() - startArr;

        // 2. Benchmark LinkedList Traversal (using Iterator/for-each)
        long startLinked = System.nanoTime();
        long sumLinked = 0;
        for (int val : linkedList) {
            sumLinked += val;
        }
        long durationLinked = System.nanoTime() - startLinked;

        System.out.println("=== Sequential Traversal Benchmark (" + COUNT + " items) ===");
        System.out.printf("ArrayList Duration:  %,d ns\n", durationArr);
        System.out.printf("LinkedList Duration: %,d ns\n", durationLinked);
        System.out.println("Sums match? " + (sumArr == sumLinked));
        System.out.println("Conclusion: Contiguous memory and CPU cache locality provide massive speedups!");
    }
}

